 out=[f'<h1>{title}</h1>',f'<p><strong>{key}</strong> موضوع این مقاله است. برای فهم دقیق آن باید میان اصل فیزیکی، نمایش آزمایشگاهی و محصول مهندسی تفاوت بگذاریم. در ادامه سازوکار را بدون فرمول سنگین توضیح می‌دهیم، مزیت ادعایی را با روش‌های معمول مقایسه می‌کنیم و محدودیت‌هایی را می‌بینیم که در تیترهای خبری اغلب حذف می‌شوند.</p>']
 bodies={
 'quantum-lidar':['لیدار پالس نور را به سوی هدف می‌فرستد و زمان بازگشت را اندازه می‌گیرد. فاصله نصف حاصل‌ضرب زمان رفت‌وبرگشت در سرعت نور است. جهت اسکن و شدت بازتاب نیز نقشه سه‌بعدی می‌سازند.','در نسخه‌های کوانتومی، آشکارسازی تک‌فوتون، نور فشرده یا هم‌بستگی میان فوتون سیگنال و مرجع بررسی می‌شود. روشن‌سازی کوانتومی می‌کوشد حضور هدف کم‌بازتاب را در نویز تشخیص دهد؛ مزیت نظری آن حتی پس از نابودی درهم‌تنیدگی در کانال ممکن است در هم‌بستگی باقی بماند.','این سامانه مانند فرستادن بلیت‌های جفت‌شده است: بازگشت بلیتی با نشانه درست، آن را از ازدحام جدا می‌کند. مرز تمثیل این است که فوتون برچسب کلاسیکی مخفی ندارد و مزیت از آمار اندازه‌گیری مشترک می‌آید.','اتلاف رفت‌وبرگشت با فاصله شدید می‌شود؛ آشکارساز تاریک‌شماری دارد و نور خورشید پس‌زمینه می‌سازد. منبع درهم‌تنیده و گیرنده مشترک نیز پیچیده‌اند. پس برد، سطح مقطع هدف و احتمال خطا باید کنار هم گزارش شوند.'],
 'slow-light':['سرعت نور در خلأ ثابت است، اما پوش یک پالس در ماده می‌تواند با سرعت گروهی متفاوت حرکت کند. اتم‌ها میدان را قطبیده می‌کنند و پاشندگی، رابطه فاز با فرکانس را تغییر می‌دهد.','در شفافیت القایی الکترومغناطیسی، یک پرتو کنترل ناحیه‌ای باریک و شفاف با پاشندگی شدید می‌سازد. پالس کاوش در این پنجره فشرده و کند می‌شود. سرعت گروهی بسیار کم به معنی کاهش c نیست.','صفی از افراد را تصور کنید که پیام را با تأخیر به نفر بعد می‌دهند. پیام جمعی دیر پیش می‌رود، هرچند هیچ فردی قانون سرعت بنیادی را نقض نمی‌کند. مرز تمثیل آن است که محیط پیوسته پیام کلاسیکی دست‌به‌دست نمی‌کند؛ میدان و برانگیزش اتمی حالت جفت‌شده می‌سازند.','در ذخیره نور، بخش فوتونی حالت به همدوسی جمعی اتم‌ها نگاشت و بعد بازیابی می‌شود. فوتون مانند گلوله‌ای ثابت نمی‌ماند. زمان ذخیره، بازده، وفاداری و پهنای باند معیارهای جداگانه‌اند.'],
 'quantum-lithography':['لیتوگرافی الگو را با نور روی ماده حساس ثبت می‌کند. پراش اجازه نمی‌دهد هر جزئیات دلخواه با یک طول موج و دهانه محدود ساخته شود. روش‌های صنعتی با عدد گشودگی، ماسک، پردازش محاسباتی و طول موج کوتاه‌تر این مرز را جابه‌جا می‌کنند.','حالت NOON فاز نسبی را N برابر سریع‌تر انباشته می‌کند و در اصل نوارهایی با دوره کوچک‌تر می‌سازد. اما ثبت آن معمولاً به جذب یا هم‌زمانی N فوتون وابسته است و احتمال رخداد با اتلاف افت می‌کند.','مانند خط‌کشی است که N نشانه هماهنگ را یکجا می‌خواند. مرز تمثیل این است که دقت بیشتر رایگان نیست؛ آماده‌سازی، انرژی و آشکارسازی منابع مصرف می‌کنند.','نمایش دو یا چند فوتون اثبات امکان اصل است، نه خط تولید تراشه. هر فوتون ازدست‌رفته حالت را خراب می‌کند و ماده مقاوم باید فرایند چندفوتونی کارآمد داشته باشد. روش کلاسیک با منبع هم‌ارز نیز باید خط مبنا باشد.'],
 'quantum-fingerprinting':['آلیس و باب دو فایل بزرگ دارند و فقط می‌خواهند بدانند برابرند یا نه. در مدل هم‌زمان، هر دو پیامی کوتاه به داور می‌فرستند. هزینه ارتباطی، نه زمان پردازنده، معیار اصلی است.','داده ابتدا با کد تصحیح خطا به رشته‌ای تبدیل می‌شود که فایل‌های متفاوت را از هم دور می‌کند. سپس نشانه‌های رشته در دامنه یا فاز یک حالت کوانتومی کد می‌شوند. داور با تداخل یا آزمون مقایسه، شباهت را تخمین می‌زند.','مانند فرستادن نمونه‌ای طراحی‌شده از دو مخزن بزرگ است. مرز تمثیل این است که اثر انگشت کوانتومی خلاصه‌ای قابل خواندن از فایل نیست؛ اندازه‌گیری اطلاعات محدودی می‌دهد و حالت را مصرف می‌کند.','مزیت به مدل ارتباط، خطای مجاز، مرجع فاز و منابع نوری وابسته است. اگر کلید مشترک یا فرض‌های کلاسیک دیگری مجاز باشند، خط مبنا تغییر می‌کند. آزمایش باید کل فوتون‌های ارسال‌شده و دفعات تکرار را حساب کند.'],
 'dilution-refrigerator':['کیوبیت‌های ابررسانا گذارهایی در بسامد مایکروویو دارند. در دمای اتاق انرژی گرمایی بسیار بزرگ‌تر است و حالت پایه جمعیت کافی ندارد. یخچال رقیق‌سازی محیط را تا چند هزارم کلوین پایین می‌آورد.','در دمای زیر حدود ۰٫۸۷ کلوین، مخلوط هلیم-۳ و هلیم-۴ به دو فاز جدا می‌شود. هلیم-۳ هنگام عبور از فاز غلیظ به فاز رقیق گرما جذب می‌کند. پمپ‌کردن و بازگرداندن هلیم-۳ چرخه پیوسته می‌سازد.','جمعیتی را تصور کنید که برای عبور به سالن دوم باید بهای انرژی بپردازد و آن را از محیط می‌گیرد. مرز تمثیل این است که اتم‌ها تصمیم نمی‌گیرند؛ آنتالپی اختلاط و آمار کوانتومی دو ایزوتوپ فرایند را تعیین می‌کند.','یخچال چند صفحه دمایی، مبدل گرما، محفظه اختلاط و عایق خلأ دارد. هر کابل کنترل گرما وارد می‌کند؛ فیلتر و حرارت‌گیر آن را در مراحل میانی دفع می‌کنند. توان سرمایش در پایین‌ترین مرحله محدود است.']}
 base=bodies[slug]
 for i,s in enumerate(sections):
  out.append(f'<h2>{s}</h2>')
