 out += ['<h2>پرسش‌های متداول</h2>']
 for q,a in faqs: out.append(f'<p><strong>{q}</strong><br>{a}</p>')
 out += ['<h2>منابع معتبر</h2>','<ol class="qpedia-scientific-sources">']
 for u,t in sources: out.append(f'<li><a href="{u}" target="_blank" rel="noopener nofollow">{t}</a></li>')
 out.append('</ol>')
 return '\n'.join(out)

